import itertools

def is_costas(p):
    n=len(p)
    vectors=set()
    for i in range(n):
        for j in range(i+1,n):
            dr=p[j]-p[i]
            dc=j-i
            if (dr,dc) in vectors:
                return False
            vectors.add((dr,dc))
    return True

solutions=[]
for perm in itertools.permutations(range(5)):
    if perm[2]==3 and is_costas(perm):
        solutions.append(perm)
print(solutions)
print('count',len(solutions))
